<include file="Public:header"/><div class="mainbox">	<div id="nav" class="mainnav_title">		<ul>			<a href="{pigcms{:U('Coupon/index')}">平台优惠券列表</a>|			<a href="{pigcms{:U('Coupon/store_list',array('coupon_id'=>$_GET['coupon_id']))}" class="on">指定店铺</a>		</ul>	</div>	<table class="search_table" width="100%">		<tr>			<td style="width:60%;">				<form action="{pigcms{:U('Coupon/store_list', array('coupon_id' => $coupon_id))}" method="get">					<input type="hidden" name="c" value="Coupon"/>					<input type="hidden" name="coupon_id" value="{pigcms{$coupon_id}"/>					<input type="hidden" name="a" value="store_list"/>					<select name="status">						<option value="0" <if condition="$status eq 0">selected="selected"</if>>全部</option>						<option value="1" <if condition="$status eq 1">selected="selected"</if>>已指定</option>						<option value="2" <if condition="$status eq 2">selected="selected"</if>>指定</option>					</select>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;					<select name="searchtype">						<option value="store_name" <if condition="$_GET['searchtype'] eq 'store_name'">selected="selected"</if>>店铺名称</option>						<option value="store_id" <if condition="$_GET['searchtype'] eq 'store_id'">selected="selected"</if>>店铺编号</option>						<option value="name" <if condition="$_GET['searchtype'] eq 'name'">selected="selected"</if>>商家名称</option>						<option value="phone" <if condition="$_GET['searchtype'] eq 'phone'">selected="selected"</if>>联系电话</option>						<option value="mer_id" <if condition="$_GET['searchtype'] eq 'mer_id'">selected="selected"</if>>商家编号</option>					</select>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;					<input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>					<input type="submit" value="查询" class="button"/>				</form>			</td>		</tr>	</table>	<form name="myform" id="myform" action="" method="post">		<div class="table-list">			<table width="100%" cellspacing="0">				<thead>					<tr>						<th width="60"><input type="checkbox" id="all"/></th>						<th width="60">编号</th>						<th width="120">商家名称</th>						<th width="120">店铺名称</th>						<!-- <th>指定店铺</th> -->						<th width="140">联系电话</th>						<th width="140">操作</th>					</tr>				</thead>				<tbody>					<if condition="is_array($storeList)">						<volist name="storeList" id="vo">							<tr>								<td store_id="{pigcms{$vo.store_id}"><input type="checkbox" name="merIds[]" class="mer_id_{pigcms{$vo.mer_id} store_id_{pigcms{$vo.store_id}" value="{pigcms{$vo.mer_id}" <if condition="!empty($vo['is_bind'])">checked</if>></td>								<td>{pigcms{$vo.store_id}</td>								<td>{pigcms{$vo.merchant_name}</td>								<td>{pigcms{$vo.name}</td>								<td>{pigcms{$vo.phone}</td>								<td class="textcenter" data-id="{pigcms{$vo.mer_id}" data-store_id="{pigcms{$vo.store_id}">									<span class="cb-enable"><label class="cb-enable <if condition="!empty($vo['is_bind'])">selected</if>"><span>指定</span><input type="radio" name="selectMerchant{pigcms{$vo['store_id']}" value="1" <if condition="!empty($vo['is_bind'])">checked="checked"</if> /></label></span>									<span class="cb-disable"><label class="cb-disable <if condition="empty($vo['is_bind'])">selected</if>"><span>解除指定</span><input type="radio" name="selectMerchant{pigcms{$vo['store_id']}" value="0" <if condition="empty($vo['is_bind'])">checked="checked"</if>/></label></span>								</td>							</tr>						</volist>						<tr>							<td class="textcenter pagebar" colspan="12">								<input type="button" value="批量指定" id="online" class="button" style="float:left;margin-right:20px;margin-top:2px;"/>								<input type="button" value="批量解除指定" id="offline" class="button" style="float:left;margin-top:2px;"/>								{pigcms{$pagebar}							</td>						</tr>					<else/>						<tr><td class="textcenter red" colspan="12">列表为空！</td></tr>					</if>				</tbody>			</table>		</div>	</form></div><script type="text/javascript">$(document).ready(function(){    $('#all').click(function(){        if ($(this).is(':checked')) {            $('input[type="checkbox"]').attr('checked', true);        } else {            $('input[type="checkbox"]').attr('checked', false);        }    });    var did = '{pigcms{$coupon_id}';    $('input[type="radio"]').click(function () {        var store_id = $(this).parents('td').data('store_id');        var obj = $(this).parents('tr').find('input[type="checkbox"]');        var type = $(this).val();        var store_ids = [];        store_ids.push(store_id);        $.post('{pigcms{:U("Coupon/change")}', {'coupon_id': did, 'type':type,'store_ids': store_ids}, function (res) {            if (res.status == 1) {                layer.msg(res.info, {offset: '10px', shift: 6, time: 2000});                if (type == 1) {                    obj.attr('checked', true);                } else {                    obj.attr('checked', false);                }            } else {                alert(res.info);            }        }, 'json');    });    $('#online').click(function () {        var store_ids = [];        $("input[name='merIds[]']:checked").each(function () {            store_ids.push($(this).parents('td').attr('store_id'));        });        if (store_ids.length == 0) {            layer.msg('请选择一条记录', {offset: '100px', shift: 6, time: 2000});        }        $.post('{pigcms{:U("Coupon/change")}', {'coupon_id': did, 'type': 1, 'store_ids': store_ids}, function (res) {            if (res.status == 1) {                location.reload();            } else {                alert(res.info);            }        }, 'json');    });    $('#offline').click(function () {        var store_ids = [];        $("input[name='merIds[]']:checked").each(function () {            store_ids.push($(this).parents('td').attr('store_id'));        });        if (store_ids.length == 0) {            layer.msg('请选择一条记录', {offset: '100px', shift: 6, time: 2000});        }        $.post('{pigcms{:U("Coupon/change")}', {'coupon_id': did, 'type': 0, 'store_ids': store_ids}, function (res) {            if (res.status == 1) {                location.reload();            } else {                alert(res.info);            }        }, 'json');    });});</script><include file="Public:footer"/>